#!/usr/bin/env node

const path = require('path');
const chalk = require('chalk');
const { installHook } = require('../src/git-utils');

const HOOK_NAME = 'prepare-commit-msg';

const HOOK_CONTENT = `#!/bin/sh
# git-commit-ai hook
# Auto-generated by git-commit-ai

COMMIT_MSG_FILE=$1
COMMIT_SOURCE=$2

if [ -z "$COMMIT_SOURCE" ]; then
  if command -v git-commit-ai >/dev/null 2>&1; then
    git-commit-ai generate --yes
    exit 1
  fi
fi
`;

function installGitHook() {
  try {
    const result = installHook(HOOK_NAME, HOOK_CONTENT);
    
    if (result.alreadyExists) {
      console.log(chalk.yellow(`⚠️  Git hook 已存在: ${result.path}`));
    } else {
      console.log(chalk.green(`✅  Git hook 已安装: ${result.path}`));
    }
    
    return result;
  } catch (error) {
    console.log(chalk.red(`❌  安装 Git hook 失败: ${error.message}`));
    process.exit(1);
  }
}

if (require.main === module) {
  installGitHook();
}

module.exports = {
  installHook: installGitHook,
  HOOK_NAME,
  HOOK_CONTENT
};
